const findImageKey = (b) => Object.keys(b || {}).find(k => (b[k]?.mimeType || '').startsWith('image/')) || '';
const imageKey = findImageKey($input.item.binary);
const binary = imageKey ? { image: $input.item.binary[imageKey] } : {};
return {
  json: { topic: $json.data?.topic || '', has_image: Boolean(imageKey) },
  binary
};

// Works for every Claude node output
function getModelText(json) {
  if (typeof json?.merged_response === 'string') return json.merged_response;
  if (Array.isArray(json?.content)) return json.content.filter(c => c.type === 'text').map(c => c.text).join('');
  return '';
}

let post = getModelText($json).trim();
if (!post) throw new Error('No LinkedIn post text was found');

// Safety net: remove dash characters used as punctuation (an AI giveaway)
post = post
  .replace(/\s*[\u2014\u2013]\s*/g, ', ')   // em / en dash
  .replace(/\s+-\s+/g, ', ')                 // spaced hyphen used as a dash
  .replace(/,\s*,/g, ',')
  .replace(/^\s*["']|["']\s*$/g, '')
  .trim();

return { json: { current_post: post } };

const findImageKey = (b) => Object.keys(b || {}).find(k => (b[k]?.mimeType || '').startsWith('image/')) || '';

// The draft that was just approved
const run = $prevNode.runIndex;
const currentPost = $('set current draft').last(0, run).json.current_post;

// Newest picture wins: a picture uploaded in a review reply, otherwise the one from the topic form
let picture = null;
for (let r = run; r >= 0 && !picture; r--) {
  let reply = null;
  try { reply = $('review draft').last(0, r); } catch (e) { reply = null; }
  const k = findImageKey(reply?.binary);
  if (k) picture = reply.binary[k];
}
if (!picture) {
  const original = $('prepare topic').first();
  if (original?.binary?.image) picture = original.binary.image;
}

const escaped = currentPost.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return {
  json: { current_post: currentPost, current_post_html: escaped, has_image: Boolean(picture), image_key: picture ? 'image' : '' },
  binary: picture ? { image: picture } : {}
};

// Bring back the approved text + picture (the email/wait steps don't carry them)
const p = $('prep linkedin post').first();
return [{ json: p.json, binary: p.binary || {} }];
